    // // inlined helper advance_to_live_card_set
    // 
    test_pass(&tg);
    test_pass(&tg);
    test_pass(&tg);
    test_pass(&tg);
    test_pass(&tg);
    // 
    test_set_live_card(&tg, 0, hanamusubi);
    test_set_live_card(&tg, 0, f1);
    test_set_live_card(&tg, 0, f2);
    // // inlined helper finish_live_setup
