    int arriver = test_id(&tg, "PL!-sd1-001-SD");
    // 
    // // Place Hanayo on stage
    tg.state.p[0].stage[1] = hanayo;
    // 
    // // Add 2 score-3 live cards → total = 6, triggers +3 cost
    // // inlined helper add_score3_live
    // 
    int live = test_id(&tg, "PL!-sd1-021-SD");
    test_add_to_success(&tg, live);
