    // TODO: tg.state.batch_movements.clear();
    // 
    int before_hand = tg.state.p[0].hand.n;
    int player_id = 0;
    rb_fire_recorded_auto(&tg.state, 0);
    rb_drain_ability_queue(&tg.state);
    // 
    // // Since a different card moved, Sumire's "this member" check should NOT trigger.
    // TODO assert_eq (unresolved): assert_eq!( // inlined helper heart02_mod  &tg.state .mods .get_heart_modifier(sumire, HeartColor::Heart02)  0, "different-card move should NOT trigger Sumire (card identity check)" );
