    int pool = 0;
    int tid = 0;
    // TODO loop (degraded): for &tid in &tids { let mut v = Vec::with_capacity(11);
    // TODO: for (int _i=0; _i<11; _i++) { v.push(db.create_copy(tid));
    // TODO: }
    // TODO: pool.insert(tid, v);
    // TODO: }
